import { useState, useEffect, useRef } from 'react';

const API      = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');
const AWAY_MS  = 10 * 60 * 1000;

export default function VivaJoin({ store }) {
  const [phase,      setPhase]     = useState('join');
  const [vivaId,     setVivaId]    = useState('');
  const [vivaInfo,   setVivaInfo]  = useState(null);
  const [loading,    setLoading]   = useState(false);
  const [error,      setError]     = useState('');

  const [invites,    setInvites]   = useState([]);
  const [loadingInv, setLoadingInv]= useState(true);
  const [results,    setResults]   = useState([]);
  const [loadingRes, setLoadingRes]= useState(true);

  const [camPerm,    setCamPerm]   = useState('prompt');
  const [micPerm,    setMicPerm]   = useState('prompt');
  const [permError,  setPermError] = useState('');
  const [camOn,      setCamOn]     = useState(true);
  const [micOn,      setMicOn]     = useState(true);

  const [awayLeft,   setAwayLeft]  = useState(null);
  const awayTimerRef = useRef(null);

  const studentVidRef = useRef(null);
  const previewVidRef = useRef(null);
  const streamRef     = useRef(null);
  const pendingVivaId = useRef(null);
  const pendingNotifId = useRef(null); // notification to dismiss after joining

  useEffect(() => {
    loadInvites();
    loadResults();
    return () => clearTimeout(awayTimerRef.current);
  }, []);

  // Away detection when in room
  useEffect(() => {
    if (phase !== 'room') return;
    const onHide = () => {
      if (document.hidden) {
        setAwayLeft(Math.floor(AWAY_MS / 1000));
        setPhase('away');
        localStorage.setItem('viva_away', JSON.stringify({ viva_id: vivaInfo?.viva_id, since: Date.now() }));
      }
    };
    document.addEventListener('visibilitychange', onHide);
    window.addEventListener('blur', onHide);
    return () => {
      document.removeEventListener('visibilitychange', onHide);
      window.removeEventListener('blur', onHide);
    };
  }, [phase, vivaInfo]);

  // Away countdown
  useEffect(() => {
    if (phase !== 'away' || awayLeft === null) return;
    if (awayLeft <= 0) {
      localStorage.removeItem('viva_away');
      stopMedia(); setPhase('join'); setVivaInfo(null);
      store.addToast('Viva session ended — you were away too long.', 'error');
      return;
    }
    awayTimerRef.current = setTimeout(() => setAwayLeft(s => s - 1), 1000);
    return () => clearTimeout(awayTimerRef.current);
  }, [phase, awayLeft]);

  // ── Load invitations ─────────────────────────────────────────
  const loadInvites = async () => {
    setLoadingInv(true);
    try {
      const r = await fetch(`${API}/notifications`, { headers:{ Authorization:`Bearer ${getToken()}` } });
      if (r.ok) {
        const all = await r.json();
        // Only show viva invitations that have a viva_room_id set
        setInvites((Array.isArray(all) ? all : []).filter(n => n.viva_room_id));
      }
    } catch {}
    setLoadingInv(false);
  };

  // ── Load viva results ─────────────────────────────────────────
  const loadResults = async () => {
    setLoadingRes(true);
    try {
      const r = await fetch(`${API}/viva/my-results`, { headers:{ Authorization:`Bearer ${getToken()}` } });
      if (r.ok) { const d = await r.json(); setResults(Array.isArray(d) ? d : []); }
    } catch {}
    setLoadingRes(false);
  };

  // ── Dismiss notification after joining ───────────────────────
  const dismissNotif = async (notifId) => {
    if (!notifId) return;
    try {
      await fetch(`${API}/notifications/${notifId}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${getToken()}` },
      });
      setInvites(prev => prev.filter(n => n.notification_id !== notifId));
    } catch {}
  };

  // ── Join flow ─────────────────────────────────────────────────
  const handleJoinClick = async (roomId, notifId = null) => {
    const cleanId = (roomId || vivaId).trim();
    if (!cleanId) { setError('Enter a Viva Room ID'); return; }
    pendingVivaId.current  = cleanId;
    pendingNotifId.current = notifId;
    setPhase('permission');
    setPermError('');
    setCamPerm('prompt'); setMicPerm('prompt');
    try {
      const s = await navigator.mediaDevices.getUserMedia({ video:true, audio:true });
      streamRef.current = s;
      setCamPerm('granted'); setMicPerm('granted');
      setTimeout(() => { if (previewVidRef.current) previewVidRef.current.srcObject = s; }, 100);
    } catch(e) {
      const msg = e.name === 'NotAllowedError'
        ? 'Camera and microphone access was denied. Click the 🔒 icon in your browser address bar → Allow.'
        : e.name === 'NotFoundError'
        ? 'No camera or microphone found. Please connect a device and try again.'
        : `Device error: ${e.message}`;
      setPermError(msg);
      setCamPerm('denied'); setMicPerm('denied');
    }
  };

  const proceedToRoom = async () => {
    const id = pendingVivaId.current;
    if (!id) return;
    setLoading(true); setError('');
    try {
      const r = await fetch(`${API}/viva/${id.trim()}`, { headers:{ Authorization:`Bearer ${getToken()}` } });
      const d = await r.json();
      if (d.error || !d.viva_id) {
        setPermError(d.error || 'Viva room not found. Check the Room ID.');
        stopMedia(); setPhase('join');
      } else {
        setVivaInfo(d);
        setCamOn(true); setMicOn(true);
        setPhase('room');
        setTimeout(() => { if (studentVidRef.current) studentVidRef.current.srcObject = streamRef.current; }, 150);
        // Dismiss the invitation notification now that student has joined
        if (pendingNotifId.current) {
          dismissNotif(pendingNotifId.current);
          pendingNotifId.current = null;
        }
        // Save student's own viva result record so it shows in their history
        await saveStudentJoinRecord(d.viva_id);
      }
    } catch { setPermError('Cannot connect to server.'); stopMedia(); setPhase('join'); }
    setLoading(false);
  };

  // Save that this student participated in this viva (so it shows in my-results)
  const saveStudentJoinRecord = async (vivaId) => {
    try {
      await fetch(`${API}/viva/${vivaId}/join`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${getToken()}`, 'Content-Type': 'application/json' },
      });
    } catch {} // non-critical — results show after admin grades
  };

  const retryPermissions = async () => {
    setPermError('');
    await handleJoinClick(pendingVivaId.current, pendingNotifId.current);
  };

  const stopMedia = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    streamRef.current = null;
  };

  const toggleCam = () => { streamRef.current?.getVideoTracks().forEach(t=>{t.enabled=!camOn;}); setCamOn(v=>!v); };
  const toggleMic = () => { streamRef.current?.getAudioTracks().forEach(t=>{t.enabled=!micOn;}); setMicOn(v=>!v); };

  const endSession = () => {
    stopMedia(); localStorage.removeItem('viva_away');
    clearTimeout(awayTimerRef.current);
    setPhase('join'); setVivaInfo(null); setAwayLeft(null);
    loadResults(); // refresh results after session
  };

  const gc   = g => g==='A+'||g==='A'?'#16a34a':g==='F'?'#dc2626':g==='B'?'#2563eb':'#d97706';
  const gcBg = g => g==='A+'||g==='A'?'#dcfce7':g==='F'?'#fee2e2':g==='B'?'#dbeafe':'#fef3c7';
  const mmFmt= s => `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`;

  // ─── AWAY PHASE ────────────────────────────────────────────────
  if (phase === 'away') return (
    <div style={{ maxWidth:520, margin:'60px auto', textAlign:'center' }}>
      <div style={{ background:'#fff', border:'2px solid #fde68a', borderRadius:20, padding:'40px 32px', boxShadow:'0 8px 32px rgba(0,0,0,.08)' }}>
        <div style={{ fontSize:56, marginBottom:16 }}>⏳</div>
        <h2 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:22, color:'#0f0f1a', marginBottom:8 }}>You Left the Viva Room</h2>
        <p style={{ fontSize:14, color:'#374151', lineHeight:1.7, marginBottom:16 }}>You navigated away. Return within the time limit to continue.</p>
        <div style={{ background:'#fef3c7', border:'1px solid #fde68a', borderRadius:12, padding:'16px 24px', marginBottom:24, display:'inline-block' }}>
          <div style={{ fontSize:11, color:'#92400e', fontFamily:'JetBrains Mono,monospace', marginBottom:4, letterSpacing:1 }}>AUTO-END IN</div>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:44, color:'#d97706', lineHeight:1 }}>{mmFmt(awayLeft||0)}</div>
        </div>
        <div style={{ display:'flex', gap:12, justifyContent:'center' }}>
          <button onClick={() => {
            clearTimeout(awayTimerRef.current);
            localStorage.removeItem('viva_away');
            setAwayLeft(null); setPhase('room');
            setTimeout(() => { if (studentVidRef.current && streamRef.current) studentVidRef.current.srcObject = streamRef.current; }, 100);
          }} style={{ padding:'12px 28px', background:'linear-gradient(135deg,#16a34a,#15803d)', color:'#fff', border:'none', borderRadius:10, fontWeight:800, fontSize:14, cursor:'pointer' }}>
            ▶ Return to Viva
          </button>
          <button onClick={endSession} style={{ padding:'12px 20px', background:'#fff', color:'#dc2626', border:'1px solid #fecaca', borderRadius:10, fontWeight:700, fontSize:13, cursor:'pointer' }}>
            End Session
          </button>
        </div>
      </div>
    </div>
  );

  // ─── PERMISSION PHASE ──────────────────────────────────────────
  if (phase === 'permission') return (
    <div style={{ maxWidth:540, margin:'32px auto' }}>
      <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:16, padding:'28px', boxShadow:'0 4px 16px rgba(0,0,0,.07)' }}>
        <h2 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:20, color:'#0f0f1a', marginBottom:4 }}>Camera & Microphone Access</h2>
        <p style={{ fontSize:13, color:'#6b7280', marginBottom:22 }}>Your camera and microphone are required for the viva examination.</p>

        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12, marginBottom:20 }}>
          {[
            { label:'Camera',      perm:camPerm, icon:'📹', ok:'Camera ready',      deny:'Camera denied',      wait:'Waiting...' },
            { label:'Microphone',  perm:micPerm, icon:'🎙', ok:'Microphone ready',  deny:'Microphone denied',  wait:'Waiting...' },
          ].map(d => (
            <div key={d.label} style={{ padding:'14px 16px', borderRadius:12, border:`1.5px solid ${d.perm==='granted'?'#bbf7d0':d.perm==='denied'?'#fecaca':'#e5e7eb'}`, background:d.perm==='granted'?'#f0fdf4':d.perm==='denied'?'#fef2f2':'#f8f8fc', display:'flex', gap:10, alignItems:'center' }}>
              <div style={{ width:36, height:36, borderRadius:9, background:d.perm==='granted'?'#dcfce7':d.perm==='denied'?'#fee2e2':'#f3f4f6', display:'flex', alignItems:'center', justifyContent:'center', fontSize:18, flexShrink:0 }}>
                {d.perm==='granted'?'✅':d.perm==='denied'?'❌':d.icon}
              </div>
              <div>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:13, color:'#0f0f1a', marginBottom:2 }}>{d.label}</div>
                <div style={{ fontSize:11, color:d.perm==='granted'?'#16a34a':d.perm==='denied'?'#dc2626':'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>
                  {d.perm==='granted'?d.ok:d.perm==='denied'?d.deny:d.wait}
                </div>
              </div>
            </div>
          ))}
        </div>

        {camPerm==='granted' && (
          <div style={{ marginBottom:20, borderRadius:12, overflow:'hidden', border:'2px solid #bbf7d0', background:'#000', aspectRatio:'16/9', position:'relative' }}>
            <video ref={previewVidRef} autoPlay muted playsInline style={{ width:'100%', height:'100%', objectFit:'cover' }}/>
            <div style={{ position:'absolute', top:10, left:10, background:'rgba(22,163,74,.9)', color:'#fff', padding:'3px 10px', borderRadius:20, fontSize:10, fontWeight:700, fontFamily:'JetBrains Mono,monospace', display:'flex', alignItems:'center', gap:5 }}>
              <span style={{ width:6, height:6, borderRadius:'50%', background:'#fff', display:'inline-block', animation:'pulse 1s ease-in-out infinite' }}/>LIVE PREVIEW
            </div>
          </div>
        )}

        {camPerm==='prompt' && (
          <div style={{ textAlign:'center', padding:'24px 0', marginBottom:16 }}>
            <div style={{ width:36, height:36, borderRadius:'50%', border:'3px solid #e8e8f0', borderTop:'3px solid #7c3aed', animation:'spin .7s linear infinite', margin:'0 auto 12px' }}/>
            <div style={{ fontSize:13, color:'#6b7280' }}>Waiting for browser permission...</div>
            <div style={{ fontSize:11, color:'#9ca3af', marginTop:4 }}>A popup should appear asking to allow camera & microphone</div>
          </div>
        )}

        {permError && (
          <div style={{ background:'#fef2f2', border:'1px solid #fecaca', borderRadius:10, padding:'12px 16px', marginBottom:16 }}>
            <div style={{ fontWeight:700, fontSize:13, color:'#dc2626', marginBottom:4 }}>⚠ Permission Error</div>
            <div style={{ fontSize:12, color:'#7f1d1d', lineHeight:1.65, marginBottom:10 }}>{permError}</div>
            <button onClick={retryPermissions} style={{ padding:'7px 18px', background:'#dc2626', color:'#fff', border:'none', borderRadius:8, fontWeight:700, fontSize:12, cursor:'pointer' }}>Try Again</button>
          </div>
        )}

        <div style={{ display:'flex', gap:10 }}>
          <button onClick={() => { stopMedia(); setPhase('join'); setPermError(''); }}
            style={{ padding:'10px 18px', background:'#fff', color:'#374151', border:'1px solid #e5e7eb', borderRadius:9, fontWeight:600, fontSize:13, cursor:'pointer' }}>← Back</button>
          {camPerm==='granted' && (
            <button onClick={proceedToRoom} disabled={loading}
              style={{ flex:1, padding:'10px', background:'linear-gradient(135deg,#16a34a,#15803d)', color:'#fff', border:'none', borderRadius:9, fontWeight:800, fontSize:14, cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center', gap:8, boxShadow:'0 4px 14px rgba(22,163,74,.3)' }}>
              {loading?<><div className="spinner" style={{width:14,height:14,borderColor:'rgba(255,255,255,.3)',borderTopColor:'#fff'}}/>Connecting...</>:'📹 Enter Viva Room'}
            </button>
          )}
        </div>
      </div>
    </div>
  );

  // ─── ROOM PHASE ────────────────────────────────────────────────
  if (phase === 'room') return (
    <div style={{ minHeight:'calc(100vh - 52px)', background:'#0d0d14', margin:'-28px -32px', padding:'14px 18px', display:'flex', flexDirection:'column', gap:12 }}>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', flexShrink:0 }}>
        <div style={{ display:'flex', alignItems:'center', gap:10 }}>
          <div style={{ display:'flex', alignItems:'center', gap:5, background:'rgba(220,38,38,.12)', border:'1px solid rgba(220,38,38,.3)', borderRadius:20, padding:'3px 10px' }}>
            <span style={{ width:6, height:6, borderRadius:'50%', background:'#dc2626', display:'inline-block', animation:'pulse 1s ease-in-out infinite' }}/>
            <span style={{ fontSize:9, fontWeight:800, color:'#fb7185', fontFamily:'JetBrains Mono,monospace', letterSpacing:1 }}>VIVA IN PROGRESS</span>
          </div>
          <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#fff' }}>{vivaInfo?.title}</span>
          {vivaInfo?.topic && <span style={{ fontSize:10, color:'rgba(255,255,255,.35)', fontFamily:'JetBrains Mono,monospace' }}>· {vivaInfo.topic}</span>}
        </div>
        <button onClick={() => { if(window.confirm('Leave the viva room?')) endSession(); }}
          style={{ padding:'5px 14px', background:'rgba(220,38,38,.15)', color:'#fb7185', border:'1px solid rgba(220,38,38,.3)', borderRadius:7, fontWeight:700, fontSize:11, cursor:'pointer' }}>
          ⏹ End Session
        </button>
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12, flex:1 }}>
        {/* Student self */}
        <div style={{ background:'#1a1a2e', borderRadius:14, overflow:'hidden', border:`1px solid ${camOn?'rgba(34,197,94,.25)':'rgba(255,255,255,.08)'}`, display:'flex', flexDirection:'column' }}>
          <div style={{ fontSize:9, fontWeight:700, color:'rgba(255,255,255,.5)', fontFamily:'JetBrains Mono,monospace', padding:'8px 14px', borderBottom:'1px solid rgba(255,255,255,.06)', display:'flex', alignItems:'center', justifyContent:'space-between' }}>
            <div style={{ display:'flex', alignItems:'center', gap:5 }}>
              <span style={{ width:5, height:5, borderRadius:'50%', background:camOn?'#22c55e':'#dc2626', display:'inline-block' }}/>
              YOU — {store.currentUser?.name?.split(' ')[0]}
            </div>
            <div style={{ display:'flex', gap:4 }}>
              {camOn&&<span style={{ background:'rgba(34,197,94,.15)', color:'#4ade80', padding:'1px 6px', borderRadius:4, fontSize:8 }}>CAM</span>}
              {micOn&&<span style={{ background:'rgba(34,197,94,.15)', color:'#4ade80', padding:'1px 6px', borderRadius:4, fontSize:8 }}>MIC</span>}
            </div>
          </div>
          <div style={{ position:'relative', flex:1, background:'#000', minHeight:260 }}>
            <video ref={studentVidRef} autoPlay muted playsInline style={{ width:'100%', height:'100%', objectFit:'cover', display:camOn?'block':'none', position:'absolute', inset:0 }}/>
            {!camOn && (
              <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:8 }}>
                <div style={{ width:60, height:60, borderRadius:'50%', background:'rgba(255,255,255,.06)', border:'2px solid rgba(255,255,255,.1)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:26 }}>
                  {store.currentUser?.name?.charAt(0).toUpperCase()}
                </div>
                <div style={{ fontSize:10, color:'rgba(255,255,255,.3)', fontFamily:'JetBrains Mono,monospace' }}>Camera Off</div>
              </div>
            )}
            {micOn && <div style={{ position:'absolute', bottom:8, right:8, background:'rgba(22,197,94,.2)', border:'1px solid rgba(22,197,94,.3)', borderRadius:20, padding:'2px 8px', display:'flex', alignItems:'center', gap:4 }}>
              <span style={{ width:5, height:5, borderRadius:'50%', background:'#22c55e', display:'inline-block', animation:'pulse 1s ease-in-out infinite' }}/>
              <span style={{ fontSize:9, color:'#4ade80', fontFamily:'JetBrains Mono,monospace' }}>LIVE</span>
            </div>}
          </div>
          <div style={{ display:'flex', gap:6, padding:8, borderTop:'1px solid rgba(255,255,255,.05)', background:'rgba(0,0,0,.3)' }}>
            <button onClick={toggleCam} style={{ flex:1, padding:'8px', borderRadius:8, border:'none', background:camOn?'rgba(34,197,94,.15)':'rgba(220,38,38,.15)', color:camOn?'#4ade80':'#fb7185', cursor:'pointer', fontSize:11, fontWeight:700 }}>{camOn?'📹 Camera On':'📷 Camera Off'}</button>
            <button onClick={toggleMic} style={{ flex:1, padding:'8px', borderRadius:8, border:'none', background:micOn?'rgba(34,197,94,.15)':'rgba(220,38,38,.15)', color:micOn?'#4ade80':'#fb7185', cursor:'pointer', fontSize:11, fontWeight:700 }}>{micOn?'🎙 Mic On':'🔇 Mic Off'}</button>
          </div>
        </div>

        {/* Examiner */}
        <div style={{ background:'#1a1a2e', borderRadius:14, overflow:'hidden', border:'1px solid rgba(109,40,217,.2)', display:'flex', flexDirection:'column' }}>
          <div style={{ fontSize:9, fontWeight:700, color:'rgba(255,255,255,.5)', fontFamily:'JetBrains Mono,monospace', padding:'8px 14px', borderBottom:'1px solid rgba(255,255,255,.06)', display:'flex', alignItems:'center', gap:5 }}>
            <span style={{ width:5, height:5, borderRadius:'50%', background:'#22c55e', display:'inline-block' }}/>
            EXAMINER
          </div>
          <div style={{ flex:1, background:'#070711', display:'flex', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:8, minHeight:260 }}>
            <div style={{ fontSize:52, opacity:.1 }}>👨‍🏫</div>
            <div style={{ fontSize:11, color:'rgba(255,255,255,.2)', fontFamily:'JetBrains Mono,monospace', textAlign:'center', lineHeight:1.7 }}>
              Examiner's camera<br/>will appear here
            </div>
          </div>
          <div style={{ padding:'8px 12px', borderTop:'1px solid rgba(255,255,255,.05)', background:'rgba(0,0,0,.3)', display:'flex', alignItems:'center', gap:8 }}>
            <div style={{ flex:1, fontSize:11, color:'rgba(255,255,255,.3)', fontFamily:'JetBrains Mono,monospace' }}>Speak clearly when asked a question</div>
            <div style={{ padding:'2px 9px', background:'rgba(109,40,217,.15)', border:'1px solid rgba(109,40,217,.25)', borderRadius:20, fontSize:9, color:'#a78bfa', fontFamily:'JetBrains Mono,monospace' }}>Active</div>
          </div>
        </div>
      </div>

      <div style={{ background:'rgba(255,255,255,.03)', border:'1px solid rgba(255,255,255,.05)', borderRadius:10, padding:'10px 16px', flexShrink:0 }}>
        <div style={{ display:'flex', gap:20, justifyContent:'center', flexWrap:'wrap' }}>
          {[
            {icon:'🎙', text:'Speak clearly and wait for your question'},
            {icon:'👁', text:'Look at the camera during answers'},
            {icon:'🔇', text:'Stay in this tab — leaving pauses the session'},
            {icon:'💡', text:'Take time to think before answering'},
          ].map((g,i) => (
            <div key={i} style={{ display:'flex', alignItems:'center', gap:6, fontSize:11, color:'rgba(255,255,255,.4)' }}>
              <span>{g.icon}</span>{g.text}
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  // ─── JOIN PHASE ────────────────────────────────────────────────
  return (
    <div className="fade-up">
      <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:24, color:'#0f0f1a', marginBottom:4 }}>🎓 Viva Voce</h1>
      <p style={{ fontSize:13, color:'#6b7280', marginBottom:22 }}>Join your scheduled oral examination session</p>

      <div style={{ display:'grid', gridTemplateColumns:'380px 1fr', gap:20, alignItems:'start' }}>
        <div style={{ display:'flex', flexDirection:'column', gap:14 }}>

          {/* Pending invitations */}
          <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:16, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
            <div style={{ padding:'13px 18px', borderBottom:'1px solid #f3f4f6', display:'flex', alignItems:'center', justifyContent:'space-between' }}>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a', display:'flex', alignItems:'center', gap:8 }}>
                📬 Viva Invitations
                {invites.length > 0 && <span style={{ background:'#7c3aed', color:'#fff', borderRadius:'50%', width:18, height:18, display:'inline-flex', alignItems:'center', justifyContent:'center', fontSize:10, fontWeight:800 }}>{invites.length}</span>}
              </div>
              <button onClick={loadInvites} style={{ padding:'3px 10px', background:'#f3f4f6', border:'1px solid #e5e7eb', borderRadius:6, fontSize:11, cursor:'pointer', color:'#374151' }}>↻</button>
            </div>

            {loadingInv ? (
              <div style={{ padding:24, display:'flex', alignItems:'center', justifyContent:'center', gap:10 }}>
                <div className="spinner" style={{width:16,height:16}}/><span style={{fontSize:13,color:'#6b7280'}}>Checking...</span>
              </div>
            ) : invites.length === 0 ? (
              <div style={{ padding:24, textAlign:'center' }}>
                <div style={{ fontSize:28, marginBottom:8, opacity:.2 }}>📭</div>
                <div style={{ fontSize:13, color:'#9ca3af' }}>No pending invitations</div>
                <div style={{ fontSize:11, color:'#d1d5db', marginTop:4 }}>Your examiner will invite you when the session starts</div>
              </div>
            ) : invites.map((inv, i) => (
              <div key={inv.notification_id||i} style={{ padding:'13px 18px', borderBottom:i<invites.length-1?'1px solid #f3f4f6':'none' }}>
                <div style={{ display:'flex', gap:10, alignItems:'flex-start' }}>
                  <div style={{ width:32, height:32, borderRadius:8, background:'#ede9fe', display:'flex', alignItems:'center', justifyContent:'center', fontSize:14, flexShrink:0 }}>🎓</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:13, color:'#0f0f1a', marginBottom:2 }}>{inv.title}</div>
                    <div style={{ fontSize:11, color:'#6b7280', lineHeight:1.55, marginBottom:7 }}>
                      {inv.message?.slice(0,100)}{inv.message?.length>100?'...':''}
                    </div>
                    {inv.viva_room_id && (
                      <div style={{ display:'flex', alignItems:'center', gap:6, marginBottom:8 }}>
                        <div style={{ background:'#ede9fe', border:'1px solid #ddd6fe', borderRadius:6, padding:'3px 9px', fontFamily:'JetBrains Mono,monospace', fontSize:10, color:'#6d28d9', fontWeight:700 }}>
                          Room: {inv.viva_room_id.slice(0,16)}...
                        </div>
                        <button onClick={()=>{ navigator.clipboard.writeText(inv.viva_room_id); store.addToast('Room ID copied!','success'); }}
                          style={{ fontSize:11, color:'#9ca3af', background:'none', border:'none', cursor:'pointer' }}>📋</button>
                      </div>
                    )}
                    <div style={{ display:'flex', gap:8, alignItems:'center' }}>
                      <button onClick={() => handleJoinClick(inv.viva_room_id, inv.notification_id)}
                        style={{ padding:'7px 16px', background:'linear-gradient(135deg,#6d28d9,#7c3aed)', color:'#fff', border:'none', borderRadius:8, fontWeight:700, fontSize:12, cursor:'pointer', display:'flex', alignItems:'center', gap:6 }}>
                        📹 Join Now
                      </button>
                      <button onClick={() => dismissNotif(inv.notification_id)}
                        style={{ padding:'5px 10px', background:'#f3f4f6', color:'#6b7280', border:'1px solid #e5e7eb', borderRadius:7, fontSize:11, cursor:'pointer' }}>
                        Dismiss
                      </button>
                      <div style={{ fontSize:10, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>
                        {inv.created_at ? new Date(inv.created_at).toLocaleDateString('en-US',{month:'short',day:'numeric'}) : ''}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Manual join */}
          <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:18, boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:13, color:'#0f0f1a', marginBottom:10 }}>🔗 Join by Room ID</div>
            <input className="form-input" value={vivaId} onChange={e=>{setVivaId(e.target.value);setError('');}}
              placeholder="Paste Room ID here" onKeyDown={e=>e.key==='Enter'&&handleJoinClick()}
              style={{ marginBottom:8, fontFamily:'JetBrains Mono,monospace', fontSize:13 }}/>
            {error && <div style={{ fontSize:12, color:'#dc2626', marginBottom:8 }}>⚠ {error}</div>}
            <button onClick={()=>handleJoinClick()} disabled={!vivaId.trim()}
              style={{ width:'100%', padding:'9px', background:vivaId.trim()?'linear-gradient(135deg,#6d28d9,#7c3aed)':'#e5e7eb', color:vivaId.trim()?'#fff':'#9ca3af', border:'none', borderRadius:9, fontWeight:700, fontSize:13, cursor:vivaId.trim()?'pointer':'not-allowed' }}>
              📹 Join Viva Room
            </button>
          </div>
        </div>

        {/* Viva results */}
        <div>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a', marginBottom:12 }}>📊 My Viva Results</div>
          {loadingRes ? (
            <div style={{ display:'flex', alignItems:'center', gap:12, padding:40, justifyContent:'center', background:'#fff', borderRadius:14, border:'1px solid #e8e8f0' }}>
              <div className="spinner" style={{width:22,height:22}}/><span style={{color:'#6b7280'}}>Loading...</span>
            </div>
          ) : results.length === 0 ? (
            <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:'36px 20px', textAlign:'center', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
              <div style={{ fontSize:36, marginBottom:10, opacity:.2 }}>🎓</div>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#374151', marginBottom:5 }}>No viva results yet</div>
              <div style={{ fontSize:13, color:'#9ca3af' }}>Results appear here after your examiner grades your session</div>
            </div>
          ) : (
            <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
              {results.map((r,i) => (
                <div key={i} style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:'15px 18px', boxShadow:'0 1px 3px rgba(0,0,0,.05)', display:'flex', gap:14, alignItems:'center' }}>
                  <div style={{ width:48, height:48, borderRadius:12, background:gcBg(r.grade), display:'flex', alignItems:'center', justifyContent:'center', fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:20, color:gc(r.grade), flexShrink:0, border:`1px solid ${gc(r.grade)}22` }}>{r.grade||'—'}</div>
                  <div style={{ flex:1 }}>
                    <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a', marginBottom:3 }}>{r.title}</div>
                    <div style={{ fontSize:11, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace', marginBottom:6 }}>{r.topic}</div>
                    <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                      <div style={{ flex:1, maxWidth:200, height:5, background:'#f3f4f6', borderRadius:3, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${r.total_score||0}%`, background:`linear-gradient(90deg,${gc(r.grade)}88,${gc(r.grade)})`, borderRadius:3 }}/>
                      </div>
                      <span style={{ fontFamily:'JetBrains Mono,monospace', fontWeight:700, fontSize:12, color:gc(r.grade) }}>{r.total_score||0}/100</span>
                    </div>
                  </div>
                  <div style={{ textAlign:'right', flexShrink:0 }}>
                    <div style={{ fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>{r.created_at?new Date(r.created_at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'-'}</div>
                    <div style={{ fontSize:11, color:'#6b7280', marginTop:3 }}>{r.questions_count||'—'} Qs</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
